import { useState, useEffect, useMemo } from "react";
import { MapContainer, TileLayer, Popup, GeoJSON, useMap, useMapEvents, Polygon, FeatureGroup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { useNavigate } from "react-router-dom";
import "../styles/AdminDashboard.css";

const API_BASE = "http://127.0.0.1:8000";

// --- Thành phần xử lý sự kiện Click để vẽ Polygon ---
function MapEvents({ drawingMode, currentPoints, setCurrentPoints }) {
    useMapEvents({
        click(e) {
            if (drawingMode) {
                const { lat, lng } = e.latlng;
                setCurrentPoints([...currentPoints, [lat, lng]]);
            }
        },
    });
    return null;
}

export default function AdminDashboard() {
    const navigate = useNavigate();
    const [activeTab, setActiveTab] = useState("territories");
    const [territories, setTerritories] = useState([]);
    const [allZones, setAllZones] = useState([]);
    const [statistics, setStatistics] = useState({});

    // States cho quản lý Phân vùng & Vẽ
    const [selectedTerritoryId, setSelectedTerritoryId] = useState(null);
    const [showTerritoryForm, setShowTerritoryForm] = useState(false);
    const [newTerritoryName, setNewTerritoryName] = useState("");
    
    // States cho việc vẽ Zone
    const [isDrawing, setIsDrawing] = useState(false);
    const [tempPoints, setTempPoints] = useState([]); // Các điểm đang vẽ dở
    const [newZoneName, setNewZoneName] = useState("");

    // States cho Sales (giữ nguyên từ bản cũ)
    const [allSales, setAllSales] = useState([]);
    const [pendingSales, setPendingSales] = useState([]);

    useEffect(() => {
        fetchInitialData();
        fetchTerritories();
        fetchSalesData();
    }, []);

    const fetchInitialData = async () => {
        try {
            const sRes = await fetch(`${API_BASE}/admin/statistics`);
            if (sRes.ok) setStatistics(await sRes.json());
            const zRes = await fetch(`${API_BASE}/zones`);
            if (zRes.ok) setAllZones(await zRes.json());
        } catch (e) { console.error("Error stats:", e); }
    };

    const fetchTerritories = async () => {
        try {
            const res = await fetch(`${API_BASE}/territories`);
            if (res.ok) setTerritories(await res.json());
        } catch (e) { console.error("Error territories:", e); }
    };

    const fetchSalesData = async () => {
        try {
            const [pRes, aRes] = await Promise.all([
                fetch(`${API_BASE}/admin/pending-sales`),
                fetch(`${API_BASE}/admin/all-sales`)
            ]);
            if (pRes.ok) setPendingSales(await pRes.json());
            if (aRes.ok) setAllSales(await aRes.json());
        } catch (e) { console.error("Error sales:", e); }
    };

    // --- Xử lý Territory ---
    const handleCreateTerritory = async () => {
        if (!newTerritoryName) return alert("Nhập tên phân vùng");
        try {
            const res = await fetch(`${API_BASE}/territories`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ name: newTerritoryName, zone_ids: [] })
            });
            if (res.ok) {
                alert("Tạo thành công");
                setNewTerritoryName("");
                setShowTerritoryForm(false);
                fetchTerritories();
            }
        } catch (e) { alert("Lỗi kết nối"); }
    };

    const handleDeleteTerritory = async (id) => {
        if (!window.confirm("Xóa phân vùng này và toàn bộ khu vực bên trong?")) return;
        try {
            await fetch(`${API_BASE}/territories/${id}`, { method: "DELETE" });
            fetchTerritories();
            setSelectedTerritoryId(null);
        } catch (e) { alert("Lỗi khi xóa"); }
    };

    // --- Xử lý Vẽ Zone ---
    const startDrawing = () => {
        if (!selectedTerritoryId) return alert("Vui lòng chọn hoặc tạo Phân vùng trước");
        setIsDrawing(true);
        setTempPoints([]);
    };

    const saveDrawnZone = async () => {
        if (tempPoints.length < 3) return alert("Cần ít nhất 3 điểm để tạo một vùng");
        if (!newZoneName) return alert("Vui lòng đặt tên cho Zone này");

        // Chuyển đổi định dạng cho GeoJSON (điểm đầu phải trùng điểm cuối)
        const coords = [...tempPoints, tempPoints[0]].map(p => [p[1], p[0]]); // Leaflet [lat,lng] -> GeoJSON [lng,lat]
        const geometry = {
            type: "Polygon",
            coordinates: [coords]
        };

        const zoneData = {
            zone_code: `Z-${Date.now()}`,
            name: newZoneName,
            district_id: 1, // Mặc định vì ta bỏ qua district
            geometry: geometry,
            center_lat: tempPoints[0][0],
            center_lng: tempPoints[0][1]
        };

        try {
            const res = await fetch(`${API_BASE}/zones`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(zoneData)
            });
            const createdZone = await res.json();

            if (res.ok) {
                // Link Zone vừa tạo vào Territory hiện tại
                const territory = territories.find(t => t.id === selectedTerritoryId);
                const updatedZoneIds = [...(territory.zone_ids || []), createdZone.id];
                
                await fetch(`${API_BASE}/territories/${selectedTerritoryId}`, {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ name: territory.name, zone_ids: updatedZoneIds })
                });

                alert("Đã lưu Zone mới vào phân vùng!");
                setIsDrawing(false);
                setTempPoints([]);
                setNewZoneName("");
                fetchTerritories();
                fetchInitialData();
            }
        } catch (e) { alert("Lỗi khi lưu Zone"); }
    };

    const deleteZone = async (zoneId) => {
        if (!window.confirm("Xóa vùng này?")) return;
        try {
            await fetch(`${API_BASE}/zones/${zoneId}`, { method: "DELETE" });
            fetchInitialData();
            fetchTerritories();
        } catch (e) { alert("Lỗi khi xóa"); }
    };

    // Lọc các Zone thuộc Phân vùng đang chọn
    const activeZones = useMemo(() => {
        const territory = territories.find(t => t.id === selectedTerritoryId);
        if (!territory || !territory.zone_ids) return [];
        return allZones.filter(z => territory.zone_ids.includes(z.id));
    }, [selectedTerritoryId, territories, allZones]);

    const getZoneColor = (index) => {
        const colors = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f', '#9b59b6', '#1abc9c', '#e67e22'];
        return colors[index % colors.length];
    };

    return (
        <div className="admin-container">
            <aside className="admin-sidebar">
                <div className="logo">🚀 Territory System</div>
                <nav className="main-nav">
                    <button className={activeTab === "dashboard" ? "active" : ""} onClick={() => setActiveTab("dashboard")}>📊 Dashboard</button>
                    <button className={activeTab === "territories" ? "active" : ""} onClick={() => setActiveTab("territories")}>🗺️ Quản lý Phân vùng</button>
                    <button className={activeTab === "sales" ? "active" : ""} onClick={() => setActiveTab("sales")}>👥 Nhân viên Sales</button>
                </nav>
                <button className="logout-btn" onClick={() => navigate("/")}>Đăng xuất</button>
            </aside>

            <main className="admin-main">
                {activeTab === "dashboard" && (
                    <div className="tab-content">
                        <h2>Tổng quan hệ thống</h2>
                        <div className="stats-grid">
                            <div className="stat-card"><h3>{allZones.length}</h3><p>Tổng số Zones tự vẽ</p></div>
                            <div className="stat-card"><h3>{territories.length}</h3><p>Tổng số Phân vùng</p></div>
                            <div className="stat-card"><h3>{allSales.length}</h3><p>Nhân viên Sales</p></div>
                        </div>
                    </div>
                )}

                {activeTab === "territories" && (
                    <div className="tab-content">
                        <div className="zone-mgr-header">
                            <h2>🗺️ Thiết kế Phân vùng & Zones tự vẽ</h2>
                            <button className="btn-primary" onClick={() => setShowTerritoryForm(true)}>➕ Tạo Phân vùng mới</button>
                        </div>

                        <div className="zone-mgr-layout">
                            {/* Danh sách Phân vùng bên trái */}
                            <div className="district-list">
                                <h4>Phân vùng của bạn</h4>
                                {territories.map(t => (
                                    <div key={t.id} className={`dist-item-wrapper ${selectedTerritoryId === t.id ? "active" : ""}`}>
                                        <div className="dist-item" onClick={() => setSelectedTerritoryId(t.id)}>
                                            📍 {t.name} ({t.zone_ids?.length || 0} vùng)
                                        </div>
                                        <button className="btn-small-del" onClick={() => handleDeleteTerritory(t.id)}>🗑️</button>
                                    </div>
                                ))}
                            </div>

                            {/* Bản đồ và Công cụ vẽ ở giữa */}
                            <div className="zone-display">
                                <div className="map-toolbar">
                                    {isDrawing ? (
                                        <div className="drawing-controls">
                                            <input 
                                                type="text" 
                                                placeholder="Đặt tên cho vùng này..." 
                                                value={newZoneName} 
                                                onChange={e => setNewZoneName(e.target.value)} 
                                            />
                                            <button className="btn-success" onClick={saveDrawnZone}>✅ Lưu vùng</button>
                                            <button className="btn-reject" onClick={() => { setIsDrawing(false); setTempPoints([]); }}>🚫 Hủy</button>
                                            <span className="draw-hint">Click lên bản đồ để vẽ các điểm. Cần ít nhất 3 điểm.</span>
                                        </div>
                                    ) : (
                                        <button className="btn-draw" onClick={startDrawing} disabled={!selectedTerritoryId}>
                                            ✏️ Bắt đầu vẽ vùng mới (Zone)
                                        </button>
                                    )}
                                </div>

                                <div className="map-box">
                                    <MapContainer center={[21.0285, 105.8542]} zoom={13} style={{ height: '500px', width: '100%' }}>
                                        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                                        
                                        <MapEvents 
                                            drawingMode={isDrawing} 
                                            currentPoints={tempPoints} 
                                            setCurrentPoints={setTempPoints} 
                                        />

                                        {/* Vẽ các điểm đang click dở */}
                                        {tempPoints.length > 0 && (
                                            <Polygon positions={tempPoints} pathOptions={{ color: 'red', dashArray: '5, 5' }} />
                                        )}

                                        {/* Hiển thị các Zone đã lưu trong Phân vùng */}
                                        {activeZones.map((z, idx) => (
                                            <GeoJSON 
                                                key={z.id} 
                                                data={z.geometry} 
                                                style={{ color: getZoneColor(idx), fillOpacity: 0.5, weight: 2 }}
                                            >
                                                <Popup>
                                                    <strong>Vùng: {z.name}</strong> <br/>
                                                    <button onClick={() => deleteZone(z.id)} style={{color: 'red', marginTop: '5px', cursor: 'pointer'}}>🗑️ Xóa vùng này</button>
                                                </Popup>
                                            </GeoJSON>
                                        ))}
                                    </MapContainer>
                                </div>
                                
                                <div className="zone-list-footer">
                                    <h4>Danh sách Zones thuộc Phân vùng này:</h4>
                                    <div className="zone-chips">
                                        {activeZones.map((z, idx) => (
                                            <div key={z.id} className="zone-chip" style={{ borderLeft: `5px solid ${getZoneColor(idx)}` }}>
                                                <span>{z.name}</span>
                                                <button onClick={() => deleteZone(z.id)}>✕</button>
                                            </div>
                                        ))}
                                        {activeZones.length === 0 && <p>Chưa có vùng nào được vẽ.</p>}
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                )}

                {/* Tab quản lý Sales (Giữ nguyên logic cũ nhưng gọn hơn) */}
                {activeTab === "sales" && (
                    <div className="tab-content">
                        <h2>👥 Quản lý Nhân viên Sales</h2>
                        <div className="sales-section">
                            <h3>Chờ duyệt ({pendingSales.length})</h3>
                            <div className="sales-grid">
                                {pendingSales.map(s => (
                                    <div key={s.id} className="sale-card">
                                        <strong>{s.full_name || s.username}</strong>
                                        <p>{s.email}</p>
                                        <button className="btn-approve" onClick={() => fetch(`${API_BASE}/admin/approve-user/${s.id}`, {method:'POST'}).then(()=>fetchSalesData())}>Duyệt</button>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )}
            </main>

            {/* Modal tạo Phân vùng */}
            {showTerritoryForm && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <h3>Tạo Phân vùng quản lý mới</h3>
                        <p>Lưu ý: Phân vùng là một nhóm chứa các Zones do bạn tự vẽ.</p>
                        <input 
                            type="text" 
                            placeholder="Tên phân vùng (VD: Khu vực Hoàn Kiếm)" 
                            value={newTerritoryName}
                            onChange={e => setNewTerritoryName(e.target.value)}
                        />
                        <div className="modal-btns">
                            <button className="btn-success" onClick={handleCreateTerritory}>Tạo ngay</button>
                            <button onClick={() => setShowTerritoryForm(false)}>Hủy</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
